// Package calc has small helpers for lists of numbers.
package calc

import (
	"strconv"
	"strings"
)

// Average returns the mean of nums. It returns 0 for an empty list.
func Average(nums []float64) float64 {
	if len(nums) == 0 {
		return 0
	}
	sum := 0.0
	for _, n := range nums {
		sum += n
	}
	return sum / float64(len(nums))
}
